  async function loadReportRows(){const client=window.vklucheAuth?.getClient?.();if(!client)return;state.data.reportLoading=true;const days=state.reportPeriod==='all'?null:+state.reportPeriod,from=days?new Date(Date.now()-days*86400000).toISOString():null,organizationId=state.role==='admin'?null:state.data.organization?.id||null,{data,error}=await client.rpc('auction_report',{p_from:from,p_to:null,p_organization_id:organizationId});state.data.reportLoading=false;state.data.reportRows=error?[]:data||[];if(error)window.toast?.(error.message);if(state.active==='reports')renderReports()}
  function reportCsv(rows){const columns=[['Автомобиль','vehicle'],['VIN','vin'],['Филиал','branch'],['Начало','started_at'],['Окончание','ended_at'],['Статус','status'],['Стартовая цена','start_price'],['Итоговая цена','final_price'],['Ставок','bid_count'],['Участников','participant_count'],['Цена победителя','winner_amount'],['Статус сделки','deal_status'],['Этап сделки','workflow_stage']],cell=value=>`"${String(value??'').replaceAll('"','""')}"`,lines=[columns.map(([label])=>cell(label)).join(';'),...rows.map(row=>columns.map(([,key])=>cell(row[key])).join(';'))],blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`vkluche-auctions-${new Date().toISOString().slice(0,10)}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
  function renderReports(){const rows=state.data.reportRows;if(rows===undefined&&!state.data.reportLoading){loadReportRows();content.innerHTML=`${pageHead('Отчёты','Аукционы, ставки, участники и результаты')}<div class="dashboard-loading">Формируем отчёт…</div>`;return}const data=rows||[],completed=data.filter(row=>['deal_confirmed','no_sale','cancelled'].includes(row.status)),deals=data.filter(row=>row.deal_status==='confirmed'),conversion=completed.length?Math.round(deals.length/completed.length*100):0,average=deals.length?Math.round(deals.reduce((sum,row)=>sum+(+row.winner_amount||0),0)/deals.length):0;content.innerHTML=`${pageHead('Отчёты',`${state.data.organization?.name||'Личная статистика'} · доступ только владельцам данных`,'<button type="button" data-dashboard-help>Как это работает?</button>')}<div class="report-toolbar"><div>${[['7','7 дней'],['30','30 дней'],['90','90 дней'],['all','Всё время']].map(([value,label])=>`<button type="button" data-report-period="${value}" class="${state.reportPeriod===value?'active':''}">${label}</button>`).join('')}</div><button type="button" class="report-export" data-report-export ${data.length?'':'disabled'}>Скачать CSV</button></div><div class="dashboard-stats">${stat(data.length,'аукционов')}${stat(data.reduce((sum,row)=>sum+(+row.bid_count||0),0),'ставок')}${stat(deals.length,'подтверждённых сделок')}${stat(`${conversion}%`,'конверсия в сделку')}${stat(rub(average),'средняя сумма сделки')}</div><section class="dashboard-block report-table-wrap"><div class="dashboard-block-head"><div><h3>Реестр результатов</h3><small>Одна строка — один аукцион</small></div><span>${data.length}</span></div>${data.length?`<table class="report-table"><thead><tr><th>Автомобиль</th><th>Период</th><th>Результат</th><th>Ставки</th><th>Цена</th><th>Сделка</th></tr></thead><tbody>${data.map(row=>`<tr data-open-listing="${row.listing_id}"><td><b>${esc(row.vehicle||'Автомобиль')}</b><small>${esc(row.vin||'VIN не указан')}${row.branch?` · ${esc(row.branch)}`:''}</small></td><td>${date(row.started_at)}<small>до ${date(row.ended_at)}</small></td><td>${esc(auctionLabels[row.status]||row.status)}</td><td>${row.bid_count}<small>${row.participant_count} участников</small></td><td>${rub(row.final_price)}</td><td>${esc(row.deal_status==='confirmed'?'Подтверждена':row.deal_status==='awaiting_buyer'?'Ожидает ответа':'—')}<small>${esc(dealStageLabels[row.workflow_stage]||'')}</small></td></tr>`).join('')}</tbody></table>`:empty('За выбранный период аукционов нет.')}</section>`}
  function searchDescription(search) {
    const f = search.filters || {}, parts = [];
    if (f.query) parts.push(f.query);
    const brands = Array.isArray(f.filterBrand) ? f.filterBrand : f.filterBrand ? [f.filterBrand] : [];
    if (brands.length) parts.push(brands.join(", "));
    if (f.city) parts.push(f.city);
    if (f.priceFrom || f.priceTo) parts.push(`цена ${f.priceFrom ? `от ${rub(f.priceFrom)}` : ""}${f.priceFrom && f.priceTo ? " " : ""}${f.priceTo ? `до ${rub(f.priceTo)}` : ""}`);
    if (f.yearFrom || f.yearTo) parts.push(`год ${f.yearFrom ? `от ${f.yearFrom}` : ""}${f.yearFrom && f.yearTo ? " " : ""}${f.yearTo ? `до ${f.yearTo}` : ""}`);
    return parts.join(" · ") || "Все автомобили";
  }
  function searchNotifications(search) {
    const channels = [search.notify_in_app && "В кабинете", search.notify_email && "По электронной почте"].filter(Boolean);
    return channels.join(" · ") || "Без уведомлений";
  }
