  function renderCreditApplications(){const rows=state.data.creditApplications||[],labels={new:'Новая',contacted:'Связались',documents:'Документы получены',sent_to_partner:'Отправлена партнёру',approved:'Одобрена',declined:'Отказ',completed:'Сделка завершена'};content.innerHTML=`${pageHead('Кредитные заявки','Предварительные расчёты и обращения клиентов. Доступно только администраторам.')}<section class="dashboard-block"><div class="dashboard-block-head"><div><h3>Очередь заявок</h3><small>Перед отправкой конкретному банку получите отдельное согласие клиента</small></div><span>${rows.length}</span></div>${rows.map(row=>`<article class="credit-application-row"><div><b>${esc(row.full_name)} · ${esc(row.vehicle_name)}</b><small>${esc(row.phone)} · ${esc(row.email)} · ${esc(row.region)}</small><small>Цена ${rub(row.vehicle_price)} · взнос ${rub(row.down_payment)} · ${row.term_months} мес. · ${row.interest_rate}% · платёж ≈ ${rub(row.estimated_monthly_payment)}</small><small>Доход: ${row.monthly_income?rub(row.monthly_income):'не указан'} · создана ${date(row.created_at)}</small></div><label>Статус<select data-credit-status="${row.id}">${Object.entries(labels).map(([value,label])=>`<option value="${value}"${row.status===value?' selected':''}>${label}</option>`).join('')}</select></label></article>`).join('')||empty('Кредитных заявок пока нет.')}</section>`}
